import 'recommendation_config.dart';
import 'risk_config.dart';

/// Configuration describing the outcome
/// for a specific answer (Yes / No / Unsure).
class AnswerConfig {
  /// Score awarded for this answer.
  final double score;

  /// Risk generated by this answer.
  final RiskConfig? risk;

  /// Recommendation generated by this answer.
  final RecommendationConfig? recommendation;

  const AnswerConfig({
    required this.score,
    this.risk,
    this.recommendation,
  });

  bool get hasRisk => risk != null;

  bool get hasRecommendation => recommendation != null;
}